#!/usr/bin/env bash
# deploy_logo_sticky.sh — GERCEK "Derive Intelligence" ucgen logosu + STICKY ust bar.
#   Tam-degistirme: HEM shells/kokpit.html (CANLI) HEM shells/kokpit2.html (onizleme) ayni, tam guncel icerik olur.
#   Kaynak = kokpit2 en guncel (PERF_PERIOD_V2 dahil) + LOGO_REAL_V1 + STICKY_TOP_V1. Mekanizma: docker build + force-recreate.
set -e
cd /opt/krb-assessment
TS=$(date +%s)
for F in shells/kokpit.html shells/kokpit2.html; do
  [ -f "$F" ] && cp "$F" "$F.bak.$TS" && echo "yedek: $F.bak.$TS"
done
printf '%s' '' | base64 -d > shells/kokpit.html
printf '%s' '' | base64 -d > shells/kokpit2.html
echo "yazildi: shells/kokpit.html + shells/kokpit2.html ($(wc -c < shells/kokpit.html) bayt her biri)"
# dogrulama: logo var, sahte D yok
grep -q 'url(#dtri)' shells/kokpit.html && echo "  ✓ gercek logo (url(#dtri)) mevcut" || { echo "HATA: logo yok"; exit 1; }
grep -q '>D</span>DER' shells/kokpit.html && { echo "HATA: sahte D hala var"; exit 1; } || echo "  ✓ sahte D/DERIVE gitmis"
grep -q 'STICKY_TOP_V1' shells/kokpit.html && echo "  ✓ sticky ust bar mevcut" || { echo "HATA: sticky yok"; exit 1; }
echo "=== docker build + recreate ==="
docker build -t krb-assessment:secure . >/tmp/build.log 2>&1 && echo "build ok" || { echo "BUILD HATASI:"; tail -20 /tmp/build.log; exit 1; }
docker compose up -d --force-recreate krb-assessment && echo "recreate ok"
echo "BITTI. Canli: /api/bi/kokpit  ·  Onizleme: /api/bi/kokpit2"
